2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns a newly built owner's {@code customerCode}, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
9	 * where CITY3 is the upper-cased first three letters of the owner's city, LAST3 the upper-cased
10	 * first three letters of the owner's last name and NNNN is a per-city 4-digit zero-padded
11	 * sequence equal to one more than the number of owners already in that city (e.g. 'LON-SMI-0007').
12	 * The code is stored in place on the built entity so it is persisted and returned. Runs after
13	 * {@link BuildOwner} and before the owner is saved, within the same transaction as the count so
14	 * the sequence advances consistently.
15	 */
16	public class AssignOwnerCustomerCode {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        long cityCount = ownerRepository.findAll().stream()
20	                .filter(existing -> owner.getCity().equalsIgnoreCase(existing.getCity()))
21	                .count();
22	        owner.setCustomerCode(customerCode(owner.getCity(), owner.getLastName(), cityCount));
23	    }
24	
25	    private static String customerCode(String city, String lastName, long cityOwnerCount) {
26	        return String.format("%s-%s-%04d", prefix(city), prefix(lastName), cityOwnerCount + 1);
27	    }
28	
29	    /** The upper-cased first three letters (fewer if the value is shorter) of the given value. */
30	    private static String prefix(String value) {
31	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
32	    }
33	}
